function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky
  brush.fillBleed(0.1); // slight transparency to give the haze effect
  brush.beginShape();
  brush.vertex(0, 0);   // top left
  brush.vertex(400, 0); // top right
  brush.vertex(400, 100); // top of the hills
  brush.vertex(0, 100);  // top of the hills
  brush.endShape(true);

  // Hills
  brush.fill("#b0a794"); // light brown
  brush.beginShape();
  brush.vertex(0, 150); // top left hill
  brush.vertex(400, 150); // top right hill
  brush.vertex(400, 250); // base of the right hill
  brush.vertex(0, 250);  // base of the left hill
  brush.endShape(true);

  // Sun
  brush.fill("#f5f2c8"); // golden yellow
  brush.beginShape();
  brush.vertex(200, 200); // center of sun
  brush.vertex(200, 100); // top of sun
  brush.vertex(150, 150); // top right of sun
  brush.vertex(250, 150); // top left of sun
  brush.endShape(true);

  // Horizon
  brush.fill("#d0c599"); // light orange
  brush.beginShape();
  brush.vertex(0, 280); // left of the horizon
  brush.vertex(400, 280); // right of the horizon
  brush.vertex(400, 360); // base of the horizon
  brush.vertex(0, 360);  // base of the horizon
  brush.endShape(true);
}
